/// <summary>
/// no es la mejor manera, pero a veces no hay mas remedio. es peligroso porque usa reflection
/// </summary>
public void init()
{
    next Init();

    FormDataObject fieldFTDBookTable = SalesTable_ds.Object(fieldNum(SalesTable, FTDBookTable));

    fieldFTDBookTable.registerOverrideMethod(
        methodStr(FormDataObject, LookupReference), //metodo a sobreescribir del campo
        formMethodStr(SalesTable, ftdFantasyBookLookup), //metodo por el que lo sobreescribimos
        this); //objeto donde esta el metodo por el que sobreescribimos
}
